import re, pathlib, html
for p in sorted(pathlib.Path('app/views').rglob('*.erb')):
 s=p.read_text()
 # Remove ERB regions, preserving text boundaries.
 chunks=re.split(r'<%.*?%>',s,flags=re.S)
 vals=[]
 for c in chunks:
  # match text between tags (including entities), skip anything with Ruby-ish template attrs
  for m in re.finditer(r'>\s*([^<>]+?)\s*<',c,re.S):
   x=html.unescape(m.group(1)).strip()
   if re.search(r'[A-Za-z]{2}',x) and not re.fullmatch(r'[-_=\s]*',x):
    if len(x)<200: vals.append(x.replace('\n',' '))
 if vals:
  print('\n'+str(p))
  for v in dict.fromkeys(vals): print('  '+v)
PY

